func carres(n int) []int {
    var r []int
    for i := range n {
        r = append(r, i*i)
    }
    return r
}

var pool = sync.Pool{New: func() any {
    return new(bytes.Buffer)
}}

func rendu(d Data) []byte {
    buf := pool.Get().(*bytes.Buffer)
    buf.Reset()
    defer pool.Put(buf)
    ecrire(buf, d)
    return buf.Bytes()
}

func chercher(ctx context.Context,
    q string) (R, error) {
    c := make(chan R)
    go func() { c <- requete(q) }()
    select {
    case r := <-c:
        return r, nil
    case <-ctx.Done():
        return R{}, ctx.Err()
    }
}
